sys_ui_page.client_script:
function confirmation() {
    var userInput = document.getElementById('userInput').value; //from HTML to client
    var userName = GlideModal.get().getPreference('sysparm_currentRec') ? GlideModal.get().getPreference('sysparm_currentRec') : g_user.userName; // from form client to here
    //var otlLength = userInput.length;
    if ((userInput)) {
        alert('Testing' + userInput + "" + userName);
        GlideModal().get().destroy(); // Close the modal
    } else {
        document.getElementById('userInput').value = "value input";
        alert('Please Enter the 6 digit OTP sent to your registered Email ID.');
    }
}


function cancellation() {
    GlideModal().get().destroy();
}

sys_ui_page.processing_script:
function  handleUserInput(userInput){
  gs.addInfoMessage('From server ' + userInput);
	g_scratchpad.otpValue = userInput;
}
